-- PANDUAN PENYUSUNAN EVIDEN ZI
-- Pilih database aplikasi sebelum mengimpor melalui phpMyAdmin atau mysql client
-- Memerlukan tabel dasar modul Progress ZI yang sudah tersedia
-- MySQL 5.7+ / MariaDB 10.4+, tanpa stored routine dan tanpa ID tetap
-- Sumber: PANDUAN PENYUSUNAN EVIDEN.xlsx / Interpretasi_LKE ZI
-- SHA-256 sumber: 59662ec2f0c598fc2cf2c8df881f276923a57e85ad12b86d4f2fcf6cf60e8d89
-- Kolom O disimpan di zi_evidence_guides.notes (Catatan/Keterangan/Penjelasan)
-- Kolom I disimpan di explanation, catatan pengumpul eviden tidak diubah
-- Tidak mengubah data kegiatan, persetujuan, PIC, file, tautan atau catatan pengumpul
-- Contoh jawaban dan nilai Excel tidak diimpor sebagai penilaian
-- Gambar contoh tersedia pada folder public/images/progress-zi/guide aplikasi terbaru

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SET @zi_guide_ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = CONVERT(0x7a695f67756964656c696e655f7375625f706f696e7473 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COLUMN_NAME = CONVERT(0x65766964656e63655f67756964655f6b6579 USING utf8mb4) COLLATE utf8mb4_unicode_ci) = 0, CONVERT(0x414c544552205441424c4520607a695f67756964656c696e655f7375625f706f696e7473602041444420434f4c554d4e206065766964656e63655f67756964655f6b657960205641524348415228353029204e554c4c USING utf8mb4) COLLATE utf8mb4_unicode_ci, 'SELECT 1');

PREPARE zi_guide_stmt FROM @zi_guide_ddl;

EXECUTE zi_guide_stmt;

DEALLOCATE PREPARE zi_guide_stmt;

SET @zi_guide_ddl = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'zi_guideline_sub_points' AND COLUMN_NAME = 'evidence_guide_key' AND NON_UNIQUE = 0) = 0, 'ALTER TABLE `zi_guideline_sub_points` ADD UNIQUE INDEX `zi_guideline_sub_points_evidence_guide_key_unique` (`evidence_guide_key`)', 'SELECT 1');

PREPARE zi_guide_stmt FROM @zi_guide_ddl;

EXECUTE zi_guide_stmt;

DEALLOCATE PREPARE zi_guide_stmt;

SET @zi_guide_ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = CONVERT(0x7a695f65766964656e636573 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COLUMN_NAME = CONVERT(0x64726976655f75726c USING utf8mb4) COLLATE utf8mb4_unicode_ci) = 0, CONVERT(0x414c544552205441424c4520607a695f65766964656e636573602041444420434f4c554d4e206064726976655f75726c602054455854204e554c4c USING utf8mb4) COLLATE utf8mb4_unicode_ci, 'SELECT 1');

PREPARE zi_guide_stmt FROM @zi_guide_ddl;

EXECUTE zi_guide_stmt;

DEALLOCATE PREPARE zi_guide_stmt;

CREATE TABLE IF NOT EXISTS `zi_evidence_guides` (
  `guide_key` VARCHAR(50) NOT NULL PRIMARY KEY,
  `source_name` VARCHAR(255) NOT NULL,
  `source_sha256` VARCHAR(64) NOT NULL,
  `source_sheet` VARCHAR(100) NOT NULL,
  `source_row` INT UNSIGNED NOT NULL,
  `group_type` VARCHAR(30) NOT NULL,
  `area_code` VARCHAR(30) NOT NULL,
  `area_title` VARCHAR(255) NOT NULL,
  `area_guidance` LONGTEXT NULL,
  `point_key` VARCHAR(50) NOT NULL,
  `point_code` VARCHAR(30) NOT NULL,
  `point_title` VARCHAR(255) NOT NULL,
  `point_guidance` LONGTEXT NULL,
  `display_code` VARCHAR(20) NOT NULL,
  `title` TEXT NOT NULL,
  `explanation` LONGTEXT NULL,
  `notes` LONGTEXT NULL,
  `answer_format` VARCHAR(50) NULL,
  `supporting_data` LONGTEXT NOT NULL,
  `images` LONGTEXT NOT NULL,
  `created_at` TIMESTAMP NULL DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seluruh DDL di atas selesai sebelum transaksi data dimulai

START TRANSACTION;

