-- Area pengungkit-1: MANAJEMEN PERUBAHAN

SET @zi_guide_area = NULL;

SET @zi_guide_area = COALESCE(@zi_guide_area, (SELECT IF(COUNT(DISTINCT a.id) = 1, MIN(a.id), NULL) FROM `zi_areas` a JOIN `zi_guideline_points` p ON p.zi_area_id = a.id JOIN `zi_guideline_sub_points` s ON s.zi_guideline_point_id = p.id WHERE a.group_type = CONVERT(0x70656e67756e676b6974 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND s.evidence_guide_key IN (CONVERT(0x726f772d39 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3130 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3132 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3133 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3134 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3136 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3137 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3138 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3230 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3231 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3232 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3233 USING utf8mb4) COLLATE utf8mb4_unicode_ci)));

SET @zi_guide_area = COALESCE(@zi_guide_area, (SELECT IF(COUNT(DISTINCT a.id) = 1, MIN(a.id), NULL) FROM `zi_guide_import_areas` a WHERE a.group_type = CONVERT(0x70656e67756e676b6974 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND a.normalized_title = CONVERT(0x6d616e616a656d656e2070657275626168616e USING utf8mb4) COLLATE utf8mb4_unicode_ci));

SET @zi_guide_area = COALESCE(@zi_guide_area, (SELECT IF(COUNT(DISTINCT a.id) = 1, MIN(a.id), NULL) FROM `zi_areas` a WHERE a.group_type = CONVERT(0x70656e67756e676b6974 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND a.code = CONVERT(0x50414e4455414e2d502d31 USING utf8mb4) COLLATE utf8mb4_unicode_ci));

INSERT INTO `zi_areas` (`code`, `name`, `description`, `group_type`, `is_active`, `created_at`, `updated_at`) SELECT CONVERT(0x50414e4455414e2d502d31 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x4d414e414a454d454e2050455255424148414e USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x70656e67756e676b6974 USING utf8mb4) COLLATE utf8mb4_unicode_ci, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE @zi_guide_area IS NULL;

SET @zi_guide_area = COALESCE(@zi_guide_area, LAST_INSERT_ID());

SET @zi_guide_point = NULL;

SET @zi_guide_point = COALESCE(@zi_guide_point, (SELECT IF(COUNT(DISTINCT p.id) = 1, MIN(p.id), NULL) FROM `zi_guideline_points` p JOIN `zi_guideline_sub_points` s ON s.zi_guideline_point_id = p.id WHERE p.zi_area_id = @zi_guide_area AND s.evidence_guide_key IN (CONVERT(0x726f772d39 USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(0x726f772d3130 USING utf8mb4) COLLATE utf8mb4_unicode_ci)));

